-- E0 ONLY (sandbox): the run journal of schema etl as read from dwh on 05.11.2026
-- (i06_step2_run_journal.sql): batch_run, job_run, job, error_log, the two history
-- views and the default privileges of schema etl. Never run against dwh or a copy.
CREATE TABLE etl.batch_run (
  batch_run_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_code varchar(100) NOT NULL, business_date date, trigger_type varchar(20) NOT NULL,
  status varchar(20) NOT NULL, extract_from timestamptz, extract_to timestamptz, started_at timestamptz,
  finished_at timestamptz, message text, created_by varchar(128), created_at timestamptz NOT NULL DEFAULT now(),
  pipeline_code varchar(100), source_batch_run_id bigint REFERENCES etl.batch_run(batch_run_id),
  run_mode varchar(20), root_batch_run_id bigint REFERENCES etl.batch_run(batch_run_id),
  resume_from_batch_run_id bigint REFERENCES etl.batch_run(batch_run_id), attempt_no integer,
  preflight_batch_run_id bigint REFERENCES etl.batch_run(batch_run_id),
  CONSTRAINT batch_run_attempt_no_check CHECK (attempt_no IS NULL OR attempt_no >= 1),
  CONSTRAINT batch_run_mode_check CHECK (run_mode IS NULL OR run_mode IN ('FULL', 'CONTINUE')),
  CONSTRAINT batch_run_status_check CHECK (status IN ('PENDING', 'RUNNING', 'SUCCESS', 'FAILED', 'CANCELLED')),
  CONSTRAINT batch_run_trigger_type_check CHECK (trigger_type IN ('MANUAL', 'SCHEDULED', 'RETRY')));
CREATE TABLE etl.job (
  job_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code varchar(100) NOT NULL UNIQUE,
  name varchar(200) NOT NULL, job_type varchar(30) NOT NULL,
  source_system_id bigint REFERENCES meta.source_system(source_system_id),
  source_object_id bigint REFERENCES meta.source_object(source_object_id),
  target_schema varchar(128), target_object varchar(128), execution_order integer NOT NULL DEFAULT 100,
  is_active boolean NOT NULL DEFAULT true, description text, created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT job_job_type_check CHECK (job_type IN ('EXTRACT', 'TRANSFORM', 'MART', 'DQ', 'MAINTENANCE')));
CREATE TABLE etl.job_run (
  job_run_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_run_id bigint REFERENCES etl.batch_run(batch_run_id), job_id bigint NOT NULL REFERENCES etl.job(job_id),
  status varchar(20) NOT NULL, extract_from timestamptz, extract_to timestamptz, started_at timestamptz,
  finished_at timestamptz, rows_read bigint NOT NULL DEFAULT 0, rows_inserted bigint NOT NULL DEFAULT 0,
  rows_updated bigint NOT NULL DEFAULT 0, rows_rejected bigint NOT NULL DEFAULT 0,
  error_count integer NOT NULL DEFAULT 0, message text, created_at timestamptz NOT NULL DEFAULT now(),
  reused_from_job_run_id bigint REFERENCES etl.job_run(job_run_id), skip_reason varchar(100),
  CONSTRAINT job_run_status_check CHECK (status IN ('PENDING', 'RUNNING', 'SUCCESS', 'FAILED', 'SKIPPED', 'CANCELLED')));
CREATE TABLE etl.error_log (
  error_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  batch_run_id bigint REFERENCES etl.batch_run(batch_run_id), job_run_id bigint REFERENCES etl.job_run(job_run_id),
  job_id bigint REFERENCES etl.job(job_id), source_object_id bigint REFERENCES meta.source_object(source_object_id),
  error_stage varchar(50), error_code varchar(100), error_message text NOT NULL, error_detail text,
  record_key jsonb, occurred_at timestamptz NOT NULL DEFAULT now(), source_pk text, application_id bigint,
  applicant_id bigint, column_name varchar(200), bad_value text, expected_value text, sql_state varchar(20),
  exception_type varchar(200), diagnostic_context jsonb);
CREATE TABLE etl.batch_contract_snapshot (batch_run_id bigint);
CREATE TABLE etl.batch_mapping_snapshot (batch_run_id bigint);
CREATE VIEW etl.v_integration_error AS
SELECT error_id, batch_run_id, job_run_id, job_id, source_object_id, error_stage, error_code, error_message,
       error_detail, record_key, source_pk, application_id, applicant_id, column_name, bad_value, expected_value,
       sql_state, exception_type, diagnostic_context, occurred_at
  FROM etl.error_log e;
CREATE VIEW etl.v_integration_run_history AS
SELECT batch_run_id, source_batch_run_id, pipeline_code, run_mode, root_batch_run_id, resume_from_batch_run_id,
       attempt_no, preflight_batch_run_id, business_date, trigger_type, status, started_at, finished_at, created_by,
       message,
       (SELECT count(*) AS count FROM etl.batch_contract_snapshot c WHERE c.batch_run_id = br.preflight_batch_run_id) AS contract_versions,
       (SELECT count(*) AS count FROM etl.batch_mapping_snapshot m WHERE m.batch_run_id = br.batch_run_id) AS mapping_versions,
       (SELECT count(*) AS count FROM etl.job_run jr WHERE jr.batch_run_id = br.batch_run_id AND jr.status::text = 'SUCCESS'::text) AS jobs_success,
       (SELECT count(*) AS count FROM etl.job_run jr WHERE jr.batch_run_id = br.batch_run_id AND jr.status::text = 'FAILED'::text) AS jobs_failed,
       (SELECT count(*) AS count FROM etl.job_run jr WHERE jr.batch_run_id = br.batch_run_id AND jr.status::text = 'SKIPPED'::text) AS jobs_skipped,
       (SELECT count(*) AS count FROM etl.job_run jr WHERE jr.batch_run_id = br.batch_run_id AND jr.status::text = 'PENDING'::text) AS jobs_pending
  FROM etl.batch_run br
 WHERE pipeline_code::text = 'ODS_TRANSFORM'::text;
GRANT SELECT, INSERT, UPDATE, DELETE ON etl.batch_run, etl.job_run, etl.job, etl.error_log,
  etl.v_integration_run_history, etl.v_integration_error TO dwh_etl;
GRANT SELECT ON etl.batch_run, etl.job_run, etl.job, etl.error_log, etl.v_integration_run_history,
  etl.v_integration_error TO dwh_app;
GRANT USAGE ON SCHEMA etl TO dwh_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA etl GRANT SELECT, INSERT, UPDATE, DELETE, TRUNCATE ON TABLES TO dwh_etl;
ALTER DEFAULT PRIVILEGES IN SCHEMA etl GRANT SELECT ON TABLES TO dwh_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA etl GRANT SELECT, UPDATE, USAGE ON SEQUENCES TO dwh_etl;
-- Earlier sandbox databases left identity sequences behind their rows: move every
-- identity sequence of the sandbox past the maximum of its column.
DO $seq$
DECLARE r record; m bigint;
BEGIN
  FOR r IN SELECT n.nspname, c.relname, a.attname FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid
             JOIN pg_namespace n ON n.oid = c.relnamespace
            WHERE a.attidentity <> '' AND n.nspname IN ('app', 'audit', 'meta', 'etl', 'secret_store') AND c.relkind = 'r' LOOP
    EXECUTE format('SELECT max(%I) FROM %I.%I', r.attname, r.nspname, r.relname) INTO m;
    IF m IS NOT NULL THEN
      PERFORM setval(pg_get_serial_sequence(format('%I.%I', r.nspname, r.relname), r.attname), m);
    END IF;
  END LOOP;
END
$seq$;
